// src/NotificationManager.js
import React, { useState } from 'react';
import { toast } from 'react-toastify';

// Utility function to convert a Base64 string to a Uint8Array
function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding)
    .replace(/-/g, '+')
    .replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
}

const NotificationManager = () => {
  const [subscribed, setSubscribed] = useState(false);

  // Replace this with your generated public key:
  const VAPID_PUBLIC_KEY = 'BATbwRarE-DR96YP6fzEZnGq_Xrj0rwbraTEJ7ZdnmtRDFKLYdSE_w4T_nTRLhee2fCMGsuYaRncXsRgaCDnsdY';

  const subscribeUser = async () => {
    if ('serviceWorker' in navigator && 'PushManager' in window) {
      try {
        const registration = await navigator.serviceWorker.ready;
        const subscription = await registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
        });
        console.log('Push subscription:', subscription);
        // Here, you should send the subscription to your server for storing.
        toast.success('Push subscription successful!');
        setSubscribed(true);
      } catch (error) {
        console.error('Failed to subscribe the user: ', error);
        toast.error('Push subscription failed!');
      }
    } else {
      toast.error('Push messaging is not supported in your browser.');
    }
  };

  return (
    <div style={{ margin: '20px 0' }}>
      {subscribed ? (
        <p style={{ color: 'green' }}>Push notifications enabled!</p>
      ) : (
        <button onClick={subscribeUser}>
          Enable Push Notifications
        </button>
      )}
    </div>
  );
};

export default NotificationManager;
